  (* [comment removed for export] *)
  Definition qlR_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 11 = Z_to_bv 64 (fS + i) /\ getr rg 12 = Z_to_bv 64 lS /\ getr rg 10 = Z_to_bv 64 0 /\ getr rg 21 = Z_to_bv 64 K /\ getr rg 9 = Z_to_bv 64 n /\ getr rg 18 = Z_to_bv 64 p /\ getr rg 8 = Z_to_bv 64 s /\ getr rg 2 = Z_to_bv 64 (s - 2144).
  Definition qlR_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S>0|21;!1,10!1,1|600;!1+22|32;!1,84!1,8|45;|31;!1,87!1,8|42;|30;!1,8:|10;!1,8<$rg;R!2'013!2+^R!3+53!2'6#1!3,715vv,9!2':15!2';2,^1!2+^R!3+53!2'6#1!3,716vv,9!2':16!2';2/K;!2+^R!3+53!2'6#1!3,718vv,9!2':18!2';2/n;!2+^R!3+53!2'6#1!3,719vv,9!2':19!2';2/p;!2+^R!3+53!2'6#1!3,71;vv,9!2':1;!2';2/s;!3+53!2'6#1!3,71=vv,9!2':1=!2';2!2'?/s;!1,8|;060;").
  Lemma qloopR_run : forall M (q : nat) regs i,
    out_agree M -> (0 < n)%Z -> qlR_inv regs i -> (0 <= i)%Z -> (fS + i + Z.of_nat q + 1 = lS)%Z ->
    exists regs',
